import React from 'react';

import {QueueIcon} from '~/src/components/QueueIcon/QueueIcon';

import {cnQueueSelect} from '../QueueSelect.classname';
import type {QueueInfo} from '../types';

export const mapQueueToSelectItem = (queue?: QueueInfo, selected = false) => {
    const queueId = queue?.key || '';

    const content = (
        <div className={cnQueueSelect('select-item', {forPopup: true})}>
            <QueueIcon queueId={queueId} className={cnQueueSelect('select-item-icon')} size={24} />
            <div className={cnQueueSelect('select-item-texts')}>
                <div className={cnQueueSelect('select-item-name')}>
                    {queue?.display || queue?.key}
                </div>
                <div data-testid={`${queueId}-key`} className={cnQueueSelect('select-item-key')}>
                    {queueId}
                </div>
            </div>
        </div>
    );

    return {
        data: queue,
        value: queueId,
        content,
        selected,
    };
};
